etl.query:

SELECT getdate() AS inicio_carga;


	INSERT INTO ejecuciones_etl (etl, inicio_carga) 
	VALUES ('etl_comun.xml',?inicio_carga);

SELECT CASE WHEN datepart(hour,getdate()) = 3 THEN 1 ELSE 0 END AS CARGA_LDAP;
TRUNCATE TABLE dim_usuarios_ldap;
SELECT letra from letras;
(&(objectCategory=person)(objectClass=user)(sAMAccountName=*$letra)(!(userAccountControl:1.2.840.113556.1.4.803:=2)))
INSERT INTO dim_usuarios_ldap (sAMAccountName, cn, userPrincipalName, distinguishedName, pwdlastset, mail, accountExpires, Description, lastLogonTimestamp, logonCount, givenName, createTimeStamp, modifyTimeStamp, whenCreated, whenChanged, extensionAttribute11, extensionAttribute12, extensionAttribute13, department, physicalDeliveryOfficeName, name, lastLogon, lockoutTime, telephoneNumber, sn, company, displayName) ) VALUES (?sAMAccountName, ?cn, ?userPrincipalName, ?distinguishedName, ?pwdlastset, ?mail, ?accountExpires, ?Description, ?lastLogonTimestamp, ?logonCount, ?givenName, ?createTimeStamp, ?modifyTimeStamp, ?whenCreated, ?whenChanged, ?extensionAttribute11, ?extensionAttribute12, ?extensionAttribute13, ?department, ?physicalDeliveryOfficeName, ?name, ?lastLogon, ?lockoutTime, ?telephoneNumber, ?sn, ?company,?displayName);

SELECT getdate() as fecha_actual
UPDATE fecha_actualizacion SET fecha_actualizacion = ?fecha_actual;
UPDATE d02BI_COMUN.dbo.ejecuciones_etl SET fin_carga=?fecha_actual WHERE etl='etl_comun.xml' and fin_carga is null and not exists (select * FROM d02BI_COMUN.dbo.ejecuciones_etl e2 WHERE e2.etl='etl_comun.xml' and e2.fin_carga is null and e2.inicio_carga>ejecuciones_etl.inicio_carga);
